<template>
  <main class="workspace">
    <header class="workspace-title"><div><p class="eyebrow">行程工作台</p><h1>计划可以变，重要安排不变。</h1><p>先确定时间和预算，再把每一天安排妥当。</p></div><a-button @click="loadHistory">查看已保存行程</a-button></header>
    <a-button v-if="run && ['failed','interrupted'].includes(run.status)" @click="retryRun" :loading="busy" style="margin-bottom:12px">从保存的查询结果重试</a-button>
    <a-alert v-if="error" type="error" :message="error" show-icon closable @close="error=''" />
    <div class="workspace-grid">
      <aside class="request-panel">
        <h2>这次想去哪里</h2>
        <a-form layout="vertical" @finish="createPlan">
          <a-form-item label="目的地"><a-input v-model:value="form.city" placeholder="城市名称" /></a-form-item>
          <div class="pair"><a-form-item label="开始日期"><input aria-label="开始日期" v-model="form.start_date" type="date" /></a-form-item><a-form-item label="结束日期"><input aria-label="结束日期" v-model="form.end_date" type="date" /></a-form-item></div>
          <a-form-item label="交通方式"><a-select v-model:value="form.transportation" :options="transportOptions" /></a-form-item>
          <a-form-item label="旅行偏好"><a-select v-model:value="preference" :options="preferenceOptions" /></a-form-item>
          <div class="pair"><a-form-item label="每日开始"><input aria-label="每日开始" v-model="form.constraints.day_start" type="time" /></a-form-item><a-form-item label="每日结束"><input aria-label="每日结束" v-model="form.constraints.day_end" type="time" /></a-form-item></div>
          <a-form-item label="总预算上限（元）"><a-input-number v-model:value="form.constraints.max_budget" :min="1" placeholder="可不填写" style="width:100%" /></a-form-item>
          <a-form-item label="每日步行上限（公里）"><a-input-number v-model:value="form.constraints.max_walk_km" :min="0.1" placeholder="仅步行模式可完整校验" style="width:100%" /></a-form-item>
          <a-form-item label="必去地点"><a-input v-model:value="mustVisit" placeholder="多个地点用逗号分隔" /></a-form-item>
          <a-form-item label="数据模式"><a-select v-model:value="form.mode" :options="modeOptions" /></a-form-item>
          <p class="mode-description">{{ form.mode==='replay' ? '离线示例仅支持北京。地点、天气、费用和路线为测试快照，不是实时出行建议；使用规则规划，不调用模型。' : '查询高德真实数据并调用已配置模型；票价、房态和开放时间需要另外确认。' }}</p>
          <a-form-item v-if="form.mode!=='replay'" label="额外要求"><a-textarea v-model:value="form.free_text_input" placeholder="补充偏好；重要限制请使用结构化输入" :rows="2" /></a-form-item>
          <a-button block type="primary" @click="createPlan" :loading="busy">{{ plan?'生成新的行程':'生成并检查行程' }}</a-button>
        </a-form>
      </aside>
      <section class="plan-panel" aria-live="polite">
        <div v-if="run && busy" class="run-state"><a-spin /><div><strong>正在安排你的行程</strong><p v-for="(e,i) in run.events" :key="i">{{ e.message }}</p></div></div>
        <template v-if="plan">
          <div class="plan-heading"><div><span class="status-label">{{ plan.mode==='replay'?'离线示例':'真实查询' }} · 版本 {{ plan.version }}</span><h2>{{ plan.city }}，{{ plan.days.length }} 天</h2><p>{{ plan.request.start_date }} 至 {{ plan.request.end_date }}</p></div><a-tag :color="plan.status==='conflicts'?'red':'gold'">{{ plan.status==='conflicts'?'存在约束冲突':plan.status==='checked'?'规则校验通过':'部分信息待确认' }}</a-tag></div>
          <div class="budget-strip"><div><span>已知与估算小计</span><strong>¥{{ plan.budget.subtotal }}</strong></div><div><span>预算上限</span><strong>{{ plan.request.constraints.max_budget ? '¥'+plan.request.constraints.max_budget : '未设置' }}</strong></div><div><span>费用未知项目</span><strong>{{ plan.budget.unknown_items }} 项</strong></div></div>
          <p class="muted">小计含估算费用，不代表最终报价。住宿按实际住宿晚数计算，最后一天不计住宿费。</p>
          <a-collapse v-if="plan.validation.length" class="validation-box" :default-active-key="['issues']"><a-collapse-panel key="issues" :header="'检查结果 · '+plan.validation.length+' 项'"><ul class="issues"><li v-for="(issue,i) in plan.validation" :key="i" :class="issue.severity"><strong>{{ issue.severity==='error'?'冲突':'待确认' }}</strong> {{ issue.day_index!==null ? '第'+(issue.day_index+1)+'天：' : '' }}{{ issue.message }}</li></ul></a-collapse-panel></a-collapse>
          <a-tabs v-model:activeKey="tab">
            <a-tab-pane key="itinerary" tab="每日安排">
              <a-tabs v-model:activeKey="activeDay" type="card"><a-tab-pane v-for="day in plan.days" :key="String(day.day_index)" :tab="'第 '+(day.day_index+1)+' 天'"><div class="day-heading"><h3>{{ day.date }}</h3><span>{{ day.activities.length }} 个活动</span></div>
                <div v-if="day.hotel" class="hotel-row"><div><strong>{{ day.hotel.name }}</strong><p>{{ day.hotel.price===null?'价格未查询': '每晚 ¥'+day.hotel.price+'（测试费用或估算）' }}</p></div><a-button size="small" :disabled="busy || !!viewVersion" @click="toggleLock(day)">{{ day.hotel_locked?'解锁住宿':'锁定住宿' }}</a-button></div>
                <ol class="timeline"><li v-for="activity in day.activities" :key="activity.id"><span class="timeline-time">{{ activity.start }}<small>{{ activity.end }}</small></span><div class="activity-body"><div class="activity-top"><h3>{{ activity.poi.name }}</h3><a-button size="small" :disabled="busy || !!viewVersion" @click="toggleLock(day,activity)">{{ activity.locked?'解锁活动':'锁定活动' }}</a-button></div><p>{{ activity.poi.address }}</p><p class="muted">{{ routeMinutes(day,activity)===null?'交通时间待确认':'前往约 '+routeMinutes(day,activity)+' 分钟' }} · {{ activity.poi.price===null?'票价待确认':'票价 ¥'+activity.poi.price+'（测试费用或估算）' }}</p><details><summary>查看信息来源</summary><p>{{ activity.poi.source.provider }} · {{ activity.poi.source.status }}</p><p>{{ activity.poi.source.detail }}</p><p>查询于 {{ activity.poi.source.queried_at }}</p></details></div></li></ol>
                <p v-for="(note,i) in day.notes" :key="i" class="muted">{{ note }}</p>
                <div class="revise-panel"><h3>只调整这一天</h3><p>其他日期保持不变，已锁定内容会保留。</p><div class="revise-controls"><a-select v-model:value="reviseAction" :options="reviseOptions" style="min-width:170px" /><a-button type="primary" :loading="busy" :disabled="!!viewVersion" @click="revise(day.day_index)">重新安排当天</a-button></div><div class="deadline-control"><label>这一天最晚结束时间 <input aria-label="当天最晚结束时间" v-model="dayEnd" type="time" /></label></div><a-textarea v-if="reviseAction==='custom'" v-model:value="instruction" :rows="2" placeholder="例如：减少购物，优先博物馆。需要真实模型。" /></div>
              </a-tab-pane></a-tabs>
            </a-tab-pane>
            <a-tab-pane key="changes" tab="修改与版本"><a-select :value="viewVersion || plan.version" :options="versions.map(v=>({value:v.version,label:'版本 '+v.version+' · '+new Date(v.updated_at).toLocaleString()}))" style="min-width:260px" @change="showVersion" /><a-button v-if="viewVersion" style="margin-left:10px" @click="refreshPlan(plan.id)">回到最新版本</a-button><p v-if="!plan.diff.length" class="muted">这一版本没有活动内容变更记录。</p><article v-for="d in plan.diff" :key="d.day_index" class="change-row"><strong>第 {{ d.day_index+1 }} 天</strong><p>移除：{{ d.removed.join('、') || '无' }}</p><p>新增：{{ d.added.join('、') || '无' }}</p><p v-if="d.hotel_changed">住宿已调整</p></article></a-tab-pane>
            <a-tab-pane key="map" tab="地点地图"><div v-if="!mapKey && plan" class="coordinate-preview"><p>地点位置示意 · 非导航地图</p><svg viewBox="0 0 760 420" role="img" aria-label="行程地点坐标示意图"><line x1="45" y1="370" x2="730" y2="370" stroke="#b7c9bf"/><line x1="45" y1="40" x2="45" y2="370" stroke="#b7c9bf"/><text x="660" y="400" fill="#66786c" font-size="13">经度方向</text><text x="10" y="25" fill="#66786c" font-size="13">纬度方向</text><g v-for="(p,i) in mapPoints" :key="p.id"><circle :cx="p.x" :cy="p.y" r="8" fill="#2e6b52"/><text :x="p.x+12" :y="p.y+4" fill="#344b3d" font-size="12">{{ i+1 }} {{ p.name }}</text></g></svg></div><div v-show="mapKey" ref="mapContainer" class="map-container"></div><p class="muted">{{ mapNotice }}</p></a-tab-pane>
            <a-tab-pane key="execution" tab="执行记录"><p class="muted">记录查询、缓存命中和重试次数，便于定位失败。费用以服务商账单为准。</p><a-table :data-source="plan.trace" :columns="traceColumns" :pagination="false" size="small" :scroll="{x:600}" /><div v-for="(x,i) in plan.llm" :key="i" class="change-row">模型用时 {{ x.elapsed_ms }} ms · token {{ x.usage?.total_tokens ?? '未返回' }}</div></a-tab-pane>
          </a-tabs>
        </template>
        <div v-else-if="!busy" class="empty-plan"><div class="empty-number">01 / 03</div><h2>一份可以继续修改的旅行计划</h2><p>设定时间和预算，生成行程后锁定重要安排，再按天调整。</p><div class="empty-steps"><span>填写出行条件</span><span>检查约束与来源</span><span>锁定后局部修改</span></div></div>
      </section>
    </div>
    <a-drawer v-model:open="historyOpen" title="已保存行程" width="420"><p v-if="!history.length">还没有已保存的行程。</p><button class="history-item" v-for="p in history" :key="p.id" @click="openSaved(p.id)"><strong>{{ p.city }} · 版本 {{ p.version }}</strong><span>{{ p.mode==='replay'?'离线示例':'真实查询' }} · {{ new Date(p.updated_at).toLocaleString() }}</span></button></a-drawer>
  </main>
</template>
<script setup lang="ts">
import {ref,reactive,computed,watch,nextTick,onMounted,onBeforeUnmount} from 'vue'
import api from '@/services/api'
import AMapLoader from '@amap/amap-jsapi-loader'
type Data = Record<string,any>
const form=reactive({city:'北京',start_date:'2026-11-05',end_date:'2026-11-07',transportation:'公共交通',accommodation:'经济型酒店',preferences:['历史文化'],free_text_input:'',mode:'replay',use_llm:true,constraints:{max_budget:null as number|null,day_start:'09:00',day_end:'18:00',must_visit:[] as string[],max_walk_km:null as number|null}})
const preference=ref('历史文化'),mustVisit=ref(''),plan=ref<Data|null>(null),run=ref<Data|null>(null),busy=ref(false),error=ref(''),tab=ref('itinerary'),activeDay=ref('0'),reviseAction=ref('indoor'),instruction=ref(''),dayEnd=ref(''),history=ref<Data[]>([]),historyOpen=ref(false),versions=ref<Data[]>([]),viewVersion=ref<number|null>(null),mapContainer=ref<HTMLElement|null>(null),mapNotice=ref('配置浏览器地图 Key 后显示地点；未配置时保留地址与坐标来源。')
const mapKey=import.meta.env.VITE_AMAP_JS_KEY
const mapPoints=computed(()=>{if(!plan.value)return [];const points:Data[]=Array.from(new Map(plan.value.days.flatMap((d:Data)=>d.activities.map((a:Data)=>[a.poi.id,a.poi]))).values()) as Data[];const xs=points.map(p=>p.longitude),ys=points.map(p=>p.latitude),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);return points.map(p=>({...p,id:String(p.id),name:String(p.name),x:80+(p.longitude-minX)/(maxX-minX||1)*480,y:340-(p.latitude-minY)/(maxY-minY||1)*270}))})
function routeMinutes(day:Data,a:Data){return day.route_checks?.[a.id] ? day.route_checks[a.id].minutes : a.leg_minutes}
let disposed=false,map:any=null
const options=(a:string[])=>a.map(value=>({value,label:value}))
const transportOptions=options(['公共交通','步行','自驾','混合']),preferenceOptions=options(['历史文化','自然风光','休闲','艺术','美食','购物'])
const modeOptions=[{value:'replay',label:'离线示例（规则规划）'},{value:'live',label:'真实高德查询 + 模型'},{value:'mcp',label:'真实高德 MCP + 模型'}]
const reviseOptions=[{value:'indoor',label:'改成室内活动'},{value:'relaxed',label:'减少活动，轻松一些'},{value:'custom',label:'用文字说明修改要求'},{value:'constraints',label:'应用左侧新的预算与限制'}]
const traceColumns=[{title:'工具',dataIndex:'tool'},{title:'状态',dataIndex:'status'},{title:'尝试次数',dataIndex:'attempts'},{title:'耗时 ms',dataIndex:'elapsed_ms'}]
function fail(e:any){error.value=typeof e.response?.data?.detail==='string'?e.response.data.detail:e.message||'操作失败，请重试'}
async function refreshPlan(id:string){plan.value=(await api.get('/api/plans/'+id)).data;versions.value=(await api.get('/api/plans/'+id+'/versions')).data;viewVersion.value=null;localStorage.setItem('trip-plan-id',id);Object.assign(form,plan.value!.request);preference.value=plan.value!.request.preferences[0]||'历史文化';mustVisit.value=plan.value!.request.constraints.must_visit.join('，')}
async function track(id:string){localStorage.setItem('trip-run-id',id);for(let n=0;n<180 && !disposed;n++){run.value=(await api.get('/api/runs/'+id)).data;if(run.value?.status==='completed'){await refreshPlan(run.value.plan_id);localStorage.removeItem('trip-run-id');return}if(['failed','interrupted'].includes(run.value?.status))throw new Error(run.value?.error?.message || '任务未完成');await new Promise(r=>setTimeout(r,500))}throw new Error('任务仍在处理，可稍后刷新查看')}
async function createPlan(){if(busy.value)return;error.value='';busy.value=true;viewVersion.value=null;try{const days=Math.round((Date.parse(form.end_date)-Date.parse(form.start_date))/86400000)+1;if(!Number.isFinite(days)||days<1||days>7)throw new Error('请选择1至7天的有效日期');form.preferences=[preference.value];form.constraints.must_visit=mustVisit.value.split(/[,，、]/).map(x=>x.trim()).filter(Boolean);const r=await api.post('/api/runs',{...form,travel_days:days});await track(r.data.id);activeDay.value='0'}catch(e){fail(e)}finally{busy.value=false}}
async function toggleLock(day:Data,activity?:Data){if(!plan.value)return;error.value='';try{const r=await api.post(`/api/plans/${plan.value.id}/lock`,{expected_version:plan.value.version,day_index:day.day_index,activity_id:activity?.id,locked:!(activity?activity.locked:day.hotel_locked)});await refreshPlan(r.data.id)}catch(e){fail(e)}}
async function revise(index:number){if(!plan.value||busy.value)return;busy.value=true;error.value='';try{const r=await api.post(`/api/plans/${plan.value.id}/revise`,{expected_version:plan.value.version,day_index:index,action:reviseAction.value,instruction:instruction.value,day_end:dayEnd.value||null,constraints:reviseAction.value==='constraints'?{...form.constraints,must_visit:mustVisit.value.split(/[,，、]/).map(x=>x.trim()).filter(Boolean)}:null});await track(r.data.id)}catch(e){fail(e)}finally{busy.value=false}}
async function retryRun(){if(!run.value)return;busy.value=true;error.value='';try{const r=await api.post(`/api/runs/${run.value.id}/retry`);await track(r.data.id)}catch(e){fail(e)}finally{busy.value=false}}
async function loadHistory(){try{history.value=(await api.get('/api/plans')).data;historyOpen.value=true}catch(e){fail(e)}}
async function openSaved(id:string){await refreshPlan(id);historyOpen.value=false;tab.value='itinerary'}
async function showVersion(value:any){if(!plan.value)return;plan.value=(await api.get(`/api/plans/${plan.value.id}?version=${value}`)).data;viewVersion.value=Number(value)}
async function drawMap(){await nextTick();if(!mapContainer.value||!plan.value)return;const key=mapKey;if(!key){mapNotice.value='尚未配置浏览器地图 Key。各地点的查询来源可在每日安排中查看。';return}try{if(import.meta.env.VITE_AMAP_SECURITY_CODE)(window as any)._AMapSecurityConfig={securityJsCode:import.meta.env.VITE_AMAP_SECURITY_CODE};const AMap=await AMapLoader.load({key,version:'2.0'});map?.destroy();map=new AMap.Map(mapContainer.value,{zoom:11});const pts=plan.value.days.flatMap((d:Data)=>d.activities.map((a:Data)=>a.poi));const markers=pts.map((p:Data)=>new AMap.Marker({position:[p.longitude,p.latitude],title:p.name}));map.add(markers);map.setFitView();mapNotice.value=plan.value.mode==='replay'?'显示测试快照中的地点，非实时导航。':'地点来自查询；路线与开放情况请出行前确认。'}catch{mapNotice.value='地图加载失败，请检查 JS API Key 和安全配置；行程数据仍可查看。'}}
watch([tab,plan],()=>{if(tab.value==='map')drawMap()})
onMounted(async()=>{const id=localStorage.getItem('trip-plan-id');if(id){try{await refreshPlan(id)}catch{localStorage.removeItem('trip-plan-id')}}const task=localStorage.getItem('trip-run-id');if(task){busy.value=true;try{await track(task)}catch(e){fail(e)}finally{busy.value=false}}})
onBeforeUnmount(()=>{disposed=true;map?.destroy()})
</script>
<style scoped>
